import itertools
def paths_all(a,b):
    res=[]
    def dfs(cur,seen,path):
        if cur==b: res.append(path[:]); return
        r,c=cur
        for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<8 and 0<=nc<8 and (nr,nc) not in seen and not blocked(nr,nc):
                seen.add((nr,nc)); path.append((nr,nc)); dfs((nr,nc),seen,path); path.pop(); seen.discard((nr,nc))
    dfs(a,{a},[a])
    return res
